1	interface ResolveSandboxBackPathArgs {
2	  pathname: string;
3	  search: string;
4	  schedulePath: string;
5	  stateFrom: unknown;
6	}
7	
8	function extractPathname(path: string): string {
9	  if (!path.startsWith('/')) return '';
10	  const q = path.indexOf('?');
11	  const h = path.indexOf('#');
12	  const cut = [q, h].filter((v) => v >= 0).sort((a, b) => a - b)[0];
13	  return cut === undefined ? path : path.slice(0, cut);
14	}
15	
16	function isSandboxPath(pathname: string): boolean {
17	  return pathname.includes('/schedule/ai-sandbox');
18	}
19	
20	export function resolveSandboxBackPath({
21	  pathname,
22	  search,
23	  schedulePath,
24	  stateFrom,
25	}: ResolveSandboxBackPathArgs): string {
26	  if (typeof stateFrom !== 'string') return schedulePath;
27	
28	  const from = stateFrom.trim();
29	  if (!from.startsWith('/')) return schedulePath;
30	  // Reject protocol-relative paths (e.g. "//example.com/..."): pushState would
31	  // navigate to an external origin or trigger a malformed-URL error.
32	  if (from.startsWith('//')) return schedulePath;
33	
34	  const fromPath = extractPathname(from);
35	  const currentPath = `${pathname}${search}`;
36	
37	  if (!fromPath) return schedulePath;
38	  if (from === currentPath) return schedulePath;
39	  if (fromPath === pathname) return schedulePath;
40	  if (isSandboxPath(fromPath)) return schedulePath;
41	
42	  return from;
43	}
