50	// ─── Timezone utilities ──────────────────────────────────────────────────
51	// Used by the constraint solver and existing-events endpoint to correctly
52	// convert between UTC timestamps (stored in DB) and local hours.
53	
54	/** Convert a UTC Date to a fractional local hour (e.g. 7.5 = 7:30 AM local). */
55	export function utcToLocalHour(date: Date, timezone: string): number {
56	  const local = new Date(date.toLocaleString('en-US', { timeZone: timezone }));
57	  return local.getHours() + local.getMinutes() / 60;
58	}
59	
60	/** Convert a local fractional hour on a given date string to a UTC Date. */
61	export function localHourToUtcDate(
62	  dateStr: string,
63	  localHour: number,
64	  timezone: string,
65	): Date {
66	  const totalMinutes = Math.round(localHour * 60);
67	  const hours = Math.floor(totalMinutes / 60);
68	  const minutes = totalMinutes % 60;
69	  const localDateStr = `${dateStr}T${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:00`;
70	
71	  const localDate = new Date(localDateStr);
72	  const utcDate = new Date(
73	    localDate.toLocaleString('en-US', { timeZone: 'UTC' }),
74	  );
75	  const tzDate = new Date(
76	    localDate.toLocaleString('en-US', { timeZone: timezone }),
77	  );
78	  const offset = utcDate.getTime() - tzDate.getTime();
79	
80	  return new Date(localDate.getTime() + offset);
81	}
