346	      if (!location)
347	        return c.json({ error: 'Location not found or access denied' }, 403);
348	
349	      const startDate = c.req.query('startDate');
350	      const endDate = c.req.query('endDate');
351	      if (!startDate || !endDate)
352	        return c.json({ error: 'Missing startDate or endDate' }, 400);
353	
354	      const dates: string[] = [];
355	      const current = new Date(`${startDate}T00:00:00`);
356	      const end = new Date(`${endDate}T00:00:00`);
357	      while (current <= end) {
358	        dates.push(current.toISOString().split('T')[0] ?? '');
359	        current.setDate(current.getDate() + 1);
360	      }
361	
362	      if (isUuid(locationId)) {
