371	            ? await scheduleRepository.findByLocationAndDateRange(
372	                schoolId,
373	                locationId,
374	                startAt,
375	                endAt,
376	              )
377	            : [];
378	
379	        const mappedEvents = dbEvents.map((row: Record<string, unknown>) => {
