391	            endHour: utcToLocalHour(end, locationTimezone),
392	          };
393	        });
394	
395	        return c.json({ events: mappedEvents, dates });
396	      }
397	
398	      return c.json({ events: [], dates });
399	    } catch (err: unknown) {
400	      const message = extractError(err);

400	      const message = extractError(err);
