1507	  curriculumId: string;
1508	  stageIndex: number;
1509	  moduleIndex: number;
1510	  stageName: string;
1511	  /** Ordered list of upcoming modules from current position forward */
1512	  upcomingModules: Array<{
1513	    moduleTitle: string;
1514	    /** "Ground Lesson" | "Sim Lesson" | "Flight Lesson" | "Solo Flight" | "Stage Check" | "Final Check" */
1515	    eventType: string;
