1558	export async function runScheduleSolver(
1559	  params: SolverParams,
1560	): Promise<SolverResult> {
1561	  const {
1562	    locationId,
1563	    schoolId,
1564	    startDate,
1565	    endDate,
1566	    selectedStudents,
1567	    selectedInstructors,
1568	    selectedAircraft,
1569	    selectedSimulators,
1570	    preferredAircraftIds = [],
1571	    callbacks,
1572	    abortSignal,
1573	  } = params;
1574	
1575	  const isAborted = () => abortSignal?.aborted === true;
1576	
1577	  // Validation
1578	  if (!startDate || !endDate) throw new Error('Missing startDate or endDate');
1579	  if (!selectedStudents?.length) throw new Error('No students selected');
1580	  if (!selectedInstructors?.length) throw new Error('No instructors selected');
1581	  if (!selectedAircraft?.length && !selectedSimulators?.length)
1582	    throw new Error('No aircraft or simulators selected');
1583	
1584	  if (callbacks?.onPhase) {
1585	    await callbacks.onPhase('loading', 'Loading scheduling data…');
1586	  }
1587	
1588	  // ── Load location timezone ──
1589	  const locInfo = await locationRepository.findByIdMinimal(locationId);
1590	  const locationTimezone = locInfo?.timezone ?? 'America/Phoenix';
1591	
1592	  // ── Load all data in parallel ──
1593	  // Use location-scoped user queries (not school-wide findByRole)
1594	  const [
1595	    locConfigRow,
1596	    studentsAtLoc,
1597	    instructorsAtLoc,
1598	    studentsNullLoc,

1600	    allEquipment,
1601	    availabilityRows,
1602	    classes,
1603	    existingDbEvents,
1604	  ] = await Promise.all([
1605	    locationConfigRepository.findByLocation(locationId),
1606	    userRepository.findByLocationAndRoleUnscoped(
1607	      schoolId,
1608	      locationId,
1609	      'student',
1610	      false,
1611	    ),
1612	    userRepository.findByLocationAndRoleUnscoped(
1613	      schoolId,
1614	      locationId,
1615	      'instructor',
1616	      false,
1617	    ),
1618	    userRepository.findBySchoolAndRoleNullLocation(schoolId, 'student', false),
1619	    userRepository.findBySchoolAndRoleNullLocation(
1620	      schoolId,
1621	      'instructor',
1622	      false,
1623	    ),
1624	    equipmentRepository.findBySchool(schoolId, locationId),
1625	    locationAvailabilityRepository.findByLocation(locationId),
1626	    classRepository.findByLocation(schoolId, locationId),
1627	    scheduleRepository.findByLocationAndDateRange(
1628	      schoolId,
1629	      locationId,
1630	      new Date(`${startDate}T00:00:00Z`),
1631	      new Date(`${endDate}T23:59:59Z`),
1632	    ),
1633	  ]);
1634	
1635	  // Merge location-assigned + school-wide (null-location) users, dedup by id
1636	  const seenStudentIds = new Set(studentsAtLoc.map((s) => s.id));
1637	  const allStudents = [
1638	    ...studentsAtLoc,
1639	    ...studentsNullLoc.filter((s) => !seenStudentIds.has(s.id)),
1640	  ];
1641	  const seenInstructorIds = new Set(instructorsAtLoc.map((i) => i.id));
1642	  const allInstructors = [
1643	    ...instructorsAtLoc,
1644	    ...instructorsNullLoc.filter((i) => !seenInstructorIds.has(i.id)),
1645	  ];
1646	
1647	  if (callbacks?.onPhase) {
1648	    await callbacks.onPhase('building_maps', 'Building resource maps…');
1649	  }
1650	
1651	  // Load class enrollments to map students → classes
1652	  const classIds = classes.map((cls: { id: string }) => cls.id);
1653	  const enrollments =
1654	    classIds.length > 0
1655	      ? await classEnrollmentRepository.findByClassIds(schoolId, classIds)
1656	      : [];
1657	
1658	  // ── Load curriculum routes for selected students ──
1659	  // Resolves each student's position in their course timeline so the solver
1660	  // can assign the correct event type (ground/sim/flight/stage check).
1661	  let studentCurriculumRoutes =
1662	    params.studentCurriculumRoutes ?? new Map<string, StudentCurriculumRoute>();
1663	
1664	  if (!params.studentCurriculumRoutes && selectedStudents.length > 0) {
1665	    try {
1666	      // Step 1: Load curriculum placements for selected students
1667	      const placements = await db
1668	        .select()
1669	        .from(schema.curriculumPlacements)
1670	        .where(
1671	          and(
1672	            eq(schema.curriculumPlacements.locationId, locationId),
1673	            inArray(schema.curriculumPlacements.studentId, selectedStudents),
1674	          ),
1675	        );
1676	
1677	      // Step 2: For students WITH placements, resolve curriculum via enrollment chain
1678	      // classEnrollments → classes → trainingCourses → curricula
1679	      const studentIdsWithPlacements = new Set(
1680	        placements.map((p) => p.studentId),
1681	      );
1682	      const allStudentIds = [...studentIdsWithPlacements];
1683	
1684	      // Also try to resolve curriculum for students WITHOUT placements
1685	      // via enrollment chain (same fallback as get_student_modules in routes-chat.ts)
1686	      const studentsWithoutPlacement = selectedStudents.filter(
1687	        (sid) => !studentIdsWithPlacements.has(sid),
1688	      );
1689	
1690	      // Resolve curriculum IDs for students with placements via enrollment chain
1691	      const studentCurriculumIdMap = new Map<string, string>();
1692	
1693	      if (allStudentIds.length > 0 || studentsWithoutPlacement.length > 0) {
1694	        const allRelevantStudentIds = [
1695	          ...allStudentIds,
1696	          ...studentsWithoutPlacement,
1697	        ];
1698	
1699	        // Path 1 (legacy): classEnrollments → classes → trainingCourses.curriculumId
1700	        const enrollmentCurrRows = await db
1701	          .select({
1702	            studentId: schema.classEnrollments.studentId,
1703	            curriculumId: schema.trainingCourses.curriculumId,
1704	          })
1705	          .from(schema.classEnrollments)
1706	          .innerJoin(
1707	            schema.classes,
1708	            eq(schema.classEnrollments.classId, schema.classes.id),
1709	          )
1710	          .innerJoin(
1711	            schema.trainingCourses,
1712	            and(
1713	              eq(schema.trainingCourses.id, schema.classes.courseId),
1714	              isNotNull(schema.trainingCourses.curriculumId),
1715	            ),
1716	          )
1717	          .where(
1718	            inArray(schema.classEnrollments.studentId, allRelevantStudentIds),
1719	          );
1720	        for (const row of enrollmentCurrRows) {
1721	          if (row.curriculumId && !studentCurriculumIdMap.has(row.studentId)) {
1722	            studentCurriculumIdMap.set(row.studentId, row.curriculumId);
1723	          }
1724	        }
1725	
1726	        // Path 1b (versioned): classEnrollments → classes →
1727	        //   trainingCourses.curriculumVersionId → curriculumVersions.curriculumId
1728	        const enrollmentVersionRows = await db
1729	          .select({
1730	            studentId: schema.classEnrollments.studentId,
1731	            curriculumId: schema.curriculumVersions.curriculumId,
1732	          })
1733	          .from(schema.classEnrollments)
1734	          .innerJoin(
1735	            schema.classes,
1736	            eq(schema.classEnrollments.classId, schema.classes.id),
1737	          )
1738	          .innerJoin(
1739	            schema.trainingCourses,
1740	            and(
1741	              eq(schema.trainingCourses.id, schema.classes.courseId),
1742	              isNotNull(schema.trainingCourses.curriculumVersionId),
1743	            ),
1744	          )
1745	          .innerJoin(
1746	            schema.curriculumVersions,
1747	            eq(
1748	              schema.curriculumVersions.id,
1749	              schema.trainingCourses.curriculumVersionId,
1750	            ),
1751	          )
1752	          .where(
1753	            inArray(schema.classEnrollments.studentId, allRelevantStudentIds),
1754	          );
1755	        for (const row of enrollmentVersionRows) {
1756	          if (row.curriculumId && !studentCurriculumIdMap.has(row.studentId)) {
1757	            studentCurriculumIdMap.set(row.studentId, row.curriculumId);
1758	          }
1759	        }
1760	      }
1761	
1762	      // Step 3: Load the curricula stages JSONB for all resolved curriculum IDs
1763	      const uniqueCurriculumIds = [...new Set(studentCurriculumIdMap.values())];
1764	      const curriculaRows =
1765	        uniqueCurriculumIds.length > 0
1766	          ? await db
1767	              .select({
1768	                id: schema.curricula.id,
1769	                stages: schema.curricula.stages,
1770	              })
1771	              .from(schema.curricula)
1772	              .where(inArray(schema.curricula.id, uniqueCurriculumIds))
1773	          : [];
1774	
1775	      type StageShape = {
1776	        name: string;
1777	        modules?: Array<{
1778	          title: string;
1779	          eventType?: string;
1780	          duration?: number;
1781	          id?: string;
1782	        }>;
1783	      };
1784	      const curriculaStagesMap = new Map<string, StageShape[]>(
1785	        curriculaRows.map((c) => [c.id, (c.stages ?? []) as StageShape[]]),
1786	      );
1787	
1788	      // Step 4: Build curriculum route map for students WITH placements
1789	      for (const p of placements) {
1790	        const curriculumId = studentCurriculumIdMap.get(p.studentId);
1791	        if (!curriculumId) continue;
1792	        const stages = curriculaStagesMap.get(curriculumId);
1793	        if (!stages || stages.length === 0) continue;
1794	
1795	        const upcomingModules: StudentCurriculumRoute['upcomingModules'] = [];
1796	        for (let si = p.stageIndex; si < stages.length; si++) {
1797	          const stage = stages[si];
1798	          const startMi = si === p.stageIndex ? p.moduleIndex : 0;
1799	          for (let mi = startMi; mi < (stage.modules?.length ?? 0); mi++) {
1800	            const mod = stage.modules![mi];
1801	            upcomingModules.push({
1802	              moduleTitle: mod.title,
1803	              eventType: mod.eventType ?? 'Flight Lesson',
1804	              durationMin: mod.duration ?? 120,
1805	              stageIndex: si,
1806	              moduleIndex: mi,
1807	              stageId: p.stageId,
1808	              moduleId: mod.id,
1809	            });
1810	          }
1811	        }
1812	
1813	        studentCurriculumRoutes.set(p.studentId, {
1814	          curriculumId,
1815	          stageIndex: p.stageIndex,
1816	          moduleIndex: p.moduleIndex,
1817	          stageName: p.stageName,
1818	          upcomingModules,
1819	        });
1820	      }
1821	
1822	      // Step 5: For students WITHOUT placements but WITH a resolved curriculum,
1823	      // start from the beginning of stage 0 / module 0
1824	      for (const sid of studentsWithoutPlacement) {
1825	        const curriculumId = studentCurriculumIdMap.get(sid);
1826	        if (!curriculumId) continue;
1827	        const stages = curriculaStagesMap.get(curriculumId);
1828	        if (!stages || stages.length === 0) continue;
1829	
1830	        const upcomingModules: StudentCurriculumRoute['upcomingModules'] = [];
1831	        for (let si = 0; si < stages.length; si++) {
1832	          const stage = stages[si];
1833	          for (let mi = 0; mi < (stage.modules?.length ?? 0); mi++) {
1834	            const mod = stage.modules![mi];
1835	            upcomingModules.push({
1836	              moduleTitle: mod.title,
1837	              eventType: mod.eventType ?? 'Flight Lesson',
1838	              durationMin: mod.duration ?? 120,
1839	              stageIndex: si,
1840	              moduleIndex: mi,
1841	              stageId: stages[si]?.name ?? '',
1842	              moduleId: mod.id,
1843	            });
1844	          }
1845	        }
1846	
1847	        studentCurriculumRoutes.set(sid, {
1848	          curriculumId,
1849	          stageIndex: 0,
1850	          moduleIndex: 0,
1851	          stageName: stages[0]?.name ?? 'Stage 1',
1852	          upcomingModules,
1853	        });
1854	      }
1855	    } catch {
1856	      // Non-blocking — if curriculum loading fails, fall back to default event types
1857	      studentCurriculumRoutes = new Map();
1858	    }
1859	  }
1860	
1861	  // ── Config ──
1862	  const aiConfig =
1863	    locConfigRow?.aiScheduleConfig &&
1864	    typeof locConfigRow.aiScheduleConfig === 'object'
1865	      ? (locConfigRow.aiScheduleConfig as Record<string, unknown>)
1866	      : {};
1867	  const opHours =
