79	function formatHourAmPm(h: number) {
80	  const hour = Math.floor(h);
81	  const min = Math.round((h - hour) * 60);
82	  const ampm = hour >= 12 ? 'PM' : 'AM';
83	  const dh = hour === 0 ? 12 : hour > 12 ? hour - 12 : hour;
84	  return min === 0
85	    ? `${dh}:00 ${ampm}`
86	    : `${dh}:${min.toString().padStart(2, '0')} ${ampm}`;
87	}
